parameters.jsCode:
// Loop over alle items
return $input.all().map(item => {
  const html = $input.first().json.data;            // jouw HTML-string
  // Zet ‘m om naar een Buffer
  item.binary = {
    htmlFile: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'output.html'
    }
  };
  // Je hebt verder geen JSON nodig, dus ruim op:
  return { json: {}, binary: item.binary };
});
